  CONSTRAINT `clinic_medicine_deleted_by_id_37fcf612_fk_auth_user_id` FOREIGN KEY (`deleted_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `clinic_medicine_chk_1` CHECK ((`current_stock` >= 0)),
  CONSTRAINT `clinic_medicine_chk_2` CHECK ((`low_stock_threshold` >= 0))
