DROP TABLE IF EXISTS `clinic_patient`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `clinic_patient` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `registration_number` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `first_name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_of_birth` date DEFAULT NULL,
  `phone` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `guardian_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registered_by_id` int NOT NULL,
  `age` int unsigned DEFAULT NULL,
  `age_unit` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `deleted_by_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `registration_number` (`registration_number`),
  KEY `clinic_patient_registered_by_id_1e0cf4a3_fk_auth_user_id` (`registered_by_id`),
  KEY `clinic_patient_deleted_by_id_94fee633_fk_auth_user_id` (`deleted_by_id`),
  KEY `clinic_patient_deleted_at_426e0dc3` (`deleted_at`),
  CONSTRAINT `clinic_patient_deleted_by_id_94fee633_fk_auth_user_id` FOREIGN KEY (`deleted_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `clinic_patient_registered_by_id_1e0cf4a3_fk_auth_user_id` FOREIGN KEY (`registered_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `clinic_patient_chk_1` CHECK ((`age` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=633 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

