DROP TABLE IF EXISTS `clinic_payment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `clinic_payment` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `service` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `approved_at` datetime(6) DEFAULT NULL,
  `approved_by_id` int DEFAULT NULL,
  `created_by_id` int NOT NULL,
  `patient_id` bigint NOT NULL,
  `department` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `doctor_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `patient_age` int unsigned DEFAULT NULL,
  `doctor_fee` decimal(10,2) NOT NULL,
  `payment_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `discount_percentage` decimal(5,2) NOT NULL,
  `discount_amount` decimal(10,2) NOT NULL,
  `patient_age_unit` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `deleted_by_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `clinic_payment_approved_by_id_14f3cbf2_fk_auth_user_id` (`approved_by_id`),
  KEY `clinic_payment_created_by_id_8708b3aa_fk_auth_user_id` (`created_by_id`),
  KEY `clinic_payment_patient_id_7ca2c8c9_fk_clinic_patient_id` (`patient_id`),
  KEY `clinic_payment_deleted_by_id_d61aff05_fk_auth_user_id` (`deleted_by_id`),
  KEY `clinic_payment_deleted_at_b4915ee5` (`deleted_at`),
  CONSTRAINT `clinic_payment_approved_by_id_14f3cbf2_fk_auth_user_id` FOREIGN KEY (`approved_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `clinic_payment_created_by_id_8708b3aa_fk_auth_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `clinic_payment_deleted_by_id_d61aff05_fk_auth_user_id` FOREIGN KEY (`deleted_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `clinic_payment_patient_id_7ca2c8c9_fk_clinic_patient_id` FOREIGN KEY (`patient_id`) REFERENCES `clinic_patient` (`id`),
  CONSTRAINT `clinic_payment_chk_1` CHECK ((`patient_age` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=615 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
